import React, { useState, useEffect, useCallback, useRef } from "react";
import CryptoJS from "crypto-js";

/*
👉 PASTE YOUR ENCRYPTED IMAGES HERE
*/
const ENCRYPTED_IMAGES = [
  "",
  "",
  "",
  "",
  "",
];

export default function App() {
  const [pin, setPin] = useState("");
  const [images, setImages] = useState([]);
  const [error, setError] = useState("");
  const [viewerOpen, setViewerOpen] = useState(false);
  const [index, setIndex] = useState(0);

  const startY = useRef(0);

  const unlock = () => {
    try {
      const decrypted = ENCRYPTED_IMAGES.map((img) => {
        const bytes = CryptoJS.AES.decrypt(img, pin);
        return bytes.toString(CryptoJS.enc.Utf8);
      });

      const valid = decrypted.every((img) => img.startsWith("data:image"));

      if (!valid) {
        setError("❌ Wrong PIN");
        setImages([]);
        return;
      }

      setError("");
      setImages(decrypted);
    } catch {
      setError("❌ Failed to decrypt");
    }
  };

  const openViewer = (i) => {
    setIndex(i);
    setViewerOpen(true);
  };

  const closeViewer = () => setViewerOpen(false);

  /* =========================
     SWIPE NAVIGATION (SAFE)
  ========================== */
  const next = useCallback(() => {
    setIndex((prev) => (prev === images.length - 1 ? 0 : prev + 1));
  }, [images.length]);

  const prev = useCallback(() => {
    setIndex((prev) => (prev === 0 ? images.length - 1 : prev - 1));
  }, [images.length]);

  /* =========================
     KEYBOARD SUPPORT
  ========================== */
  useEffect(() => {
    const handleKey = (e) => {
      if (!viewerOpen) return;

      if (e.key === "ArrowDown") next();
      if (e.key === "ArrowUp") prev();
      if (e.key === "Escape") closeViewer();
    };

    window.addEventListener("keydown", handleKey);
    return () => window.removeEventListener("keydown", handleKey);
  }, [viewerOpen, next, prev]);

  /* =========================
     TOUCH SWIPE SUPPORT
  ========================== */
  const handleTouchStart = (e) => {
    startY.current = e.touches[0].clientY;
  };

  const handleTouchEnd = (e) => {
    const endY = e.changedTouches[0].clientY;

    if (startY.current - endY > 50) next();
    if (endY - startY.current > 50) prev();
  };

  return (
    <div style={styles.page}>
      <h1 style={styles.title}>📸 PictureHub</h1>

      {/* =========================
          LOGIN SCREEN
      ========================== */}
      {!viewerOpen && images.length === 0 && (
        <div style={styles.lockBox}>
          <input
            type="password"
            placeholder="Enter PIN"
            value={pin}
            onChange={(e) => setPin(e.target.value)}
            style={styles.input}
          />

          <button onClick={unlock} style={styles.button}>
            Unlock Gallery
          </button>

          {error && <p style={{ color: "#f87171", marginTop: 10 }}>{error}</p>}
        </div>
      )}

      {/* =========================
          GRID VIEW
      ========================== */}
      {!viewerOpen && images.length > 0 && (
        <div style={styles.grid}>
          {images.map((img, i) => (
            <div key={i} style={styles.card} onClick={() => openViewer(i)}>
              <img src={img} style={styles.image} alt={`Gallery item ${i}`} />
            </div>
          ))}
        </div>
      )}

      {/* =========================
          TIKTOK SWIPE VIEWER
      ========================== */}
      {viewerOpen && (
        <div
          style={styles.viewer}
          onTouchStart={handleTouchStart}
          onTouchEnd={handleTouchEnd}
        >
          <button style={styles.close} onClick={closeViewer}>
            ✕
          </button>

          <div style={styles.counter}>
            {index + 1} / {images.length}
          </div>

          <img
            src={images[index]}
            style={styles.fullImage}
            alt={`Gallery item ${index}`}
          />

          <div style={styles.hint}>Swipe ↑ ↓ or use arrow keys</div>
        </div>
      )}
    </div>
  );
}

/* =========================
   STYLES
========================= */

const styles = {
  page: {
    minHeight: "100vh",
    background: "radial-gradient(circle at top, #0f172a, #020617)",
    padding: 30,
    color: "white",
    fontFamily: "sans-serif",
  },

  title: {
    textAlign: "center",
    fontSize: "20px",
    marginBottom: "24px",
    fontWeight: "900",
    letterSpacing: "-1px",
    fontFamily: "'Inter','Segoe UI','Roboto','Helvetica Neue',sans-serif",
    background: "linear-gradient(90deg,#6366f1,#a855f7,#22d3ee)",
    WebkitBackgroundClip: "text",
    WebkitTextFillColor: "transparent",
    textShadow: "0 10px 30px rgba(99,102,241,0.15)",
  },

  lockBox: {
    textAlign: "center",
    marginTop: 80,
  },

  input: {
    padding: 14,
    borderRadius: 12,
    border: "none",
    marginRight: 10,
    outline: "none",
  },

  button: {
    padding: "14px 18px",
    borderRadius: 12,
    border: "none",
    background: "#6366f1",
    color: "white",
    fontWeight: "bold",
    cursor: "pointer",
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit, minmax(180px, 1fr))",
    gap: 15,
  },

  card: {
    borderRadius: 16,
    overflow: "hidden",
    cursor: "pointer",
  },

  image: {
    width: "100%",
    height: 220,
    objectFit: "cover",
    display: "block",
  },

  viewer: {
    position: "fixed",
    inset: 0,
    background: "black",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    flexDirection: "column",
  },

  fullImage: {
    maxHeight: "85vh",
    maxWidth: "95vw",
    borderRadius: 16,
  },

  close: {
    position: "absolute",
    top: 20,
    right: 20,
    fontSize: 28,
    background: "transparent",
    border: "none",
    color: "white",
    cursor: "pointer",
  },

  counter: {
    position: "absolute",
    top: 20,
    left: 20,
    fontSize: 14,
    opacity: 0.7,
  },

  hint: {
    position: "absolute",
    bottom: 20,
    fontSize: 12,
    opacity: 0.5,
  },
};
